#!/bin/bash
# Task 130-w5-framework-vs-ref -- meshsim sim/ WORKER5 (branch sim-w5 a228eee). TIMING TASK: keep the box quiet while it runs.
# The first direct measure of the framework against ref (sim/ref, v1.3's Java simulator) on the same program: bench_controller's
# loop (9 instructions in 13 cycles: data load and store, ALU, a multiply, a register-block load, a taken branch; then
# SIM_EXIT), booted in ref exactly as TraceRun boots a golden (tests/ref/SpeedRun.java: the observer off). All on CPU 0 (a
# P-core; D13), clang release for the framework (D18).
#   1. like for like: at N = 1000 the loop's trace from ref (TraceRun, observer on) equals the framework's, body and closing
#      block; at every N ref and the framework report the same instructions and cycles;
#   2. ref, idle-skip on (the default: the other 63 tiles idle, skipped): N = 10^6, 4 runs in one JVM (the first warms the
#      JIT); the framework at N = 10^6 and 10^7, 3 runs each;
#   3. ref, idle-skip off (-Dmeshsim.skip=false: every unit of the 64 tiles stepped every cycle): N = 10^4, 4 runs; the
#      framework at N = 10^4;
#   4. JFR of ref (settings=profile): idle-skip on at N = 10^6 and off at N = 10^4, each folded by JfrFold (WORKER28/29).
# From an embedded kit (sim/ at a228eee with sim/ref; JfrFold and Callers). Expected ~6 min. Writes only
# results/130-w5-framework-vs-ref/. Scratch in /tmp, removed first and at the end. Safe to re-run.
set -u
cd "$(dirname "$0")/.."
REPO=$PWD; RES=$REPO/results/130-w5-framework-vs-ref; mkdir -p "$RES"
W=/tmp/w5-130; rm -rf "$W"; mkdir -p "$W"
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "df30f736032dd279fba3eb5c8361cbd4590d7427418a016d35f14e8fc178e172" ] || { echo "kit sha256 mismatch (want df30f736032dd279fba3eb5c8361cbd4590d7427418a016d35f14e8fc178e172)"; exit 2; }
mkdir -p "$W/kit" && tar -xzf "$W/kit.tgz" -C "$W/kit" || exit 2
FAIL=0
sec() { echo; echo "==== $*  [$(date +%T)]"; }
verdict() { echo "VERDICT $1: $2"; [ "$2" = PASS ] || FAIL=1; }
START=$(date +%s)
{
sec "machine"; uname -r; nproc; lscpu | grep -E 'Model name|^CPU\(s\)|Thread'; uptime; clang++ --version | head -1; java -version 2>&1 | head -1
cd "$W/kit/sim" || exit 2
SIM=$PWD; REF=$SIM/ref/meshsim; B=$SIM/build/clang-release; J="java -Xmx1g"
sec "build: the framework (clang release), ref (as regen.sh builds it), SpeedRun and TraceRun, the JFR tools"
make -j12 CC_NAME=clang MODE=release build/clang-release/bench_controller > "$RES/build.log" 2>&1 || { tail -20 "$RES/build.log"; verdict build FAIL; }
mkdir -p "$W/ref" "$W/tr" "$W/jt"
javac -d "$W/ref" "$REF"/src/*.java >> "$RES/build.log" 2>&1 || verdict "javac ref" FAIL
grep -v '^#' "$REF/test/PENDING" | awk 'NF{print "'"$REF"'/test/"$1}' > "$W/pending.txt"
javac -d "$W/ref" -cp "$W/ref" $(ls "$REF"/test/*.java | grep -v -x -F -f "$W/pending.txt") >> "$RES/build.log" 2>&1 || verdict "javac ref tests" FAIL
javac -d "$W/tr" -cp "$W/ref" "$SIM/tests/ref/SpeedRun.java" "$SIM/tests/ref/TraceRun.java" >> "$RES/build.log" 2>&1 || verdict "javac SpeedRun" FAIL
javac -d "$W/jt" "$W/kit/jfrtools"/*.java >> "$RES/build.log" 2>&1 || verdict "javac JFR tools" FAIL
CP="$W/ref:$W/tr"
sec "1. like for like: the loop's trace at N = 1000, ref against the framework"
mkdir -p "$W/l3" "$W/l4" "$W/l6"
$B/bench_controller --iters 1000 --write "$W/l3"
(cd "$REF" && $J -Dmeshsim.observe=on -cp "$CP" TraceRun "$W/l3/loop.ref.trace" 0 "$W/l3" loop) > "$W/tr.log" 2>&1 || { cat "$W/tr.log"; }
grep -v '^#' "$W/l3/loop.trace" > "$W/a"; grep -v '^#' "$W/l3/loop.ref.trace" > "$W/b"
wc -l "$W/a" "$W/b"; tail -4 "$W/b"
cmp -s "$W/a" "$W/b" && verdict "the loop's trace: ref = framework (N = 1000, body and closing)" PASS \
  || { diff "$W/a" "$W/b" | head -20; verdict "the loop's trace: ref = framework (N = 1000, body and closing)" FAIL; }
$B/bench_controller --iters 10000 --write "$W/l4" | tail -1
$B/bench_controller --iters 1000000 --write "$W/l6" | tail -1
sec "2a. ref, idle-skip on, N = 10^6: 4 runs in one JVM (run 1 warms the JIT)"
(cd "$REF" && taskset -c 0 $J -cp "$CP" SpeedRun 0 "$W/l6/loop.code.bin" 4) | tee "$RES/ref-skip-on.txt"
sec "2b. the framework, N = 10^6 and 10^7, 3 runs each"
taskset -c 0 $B/bench_controller --iters 1000000 --reps 3 --only engine | tee "$RES/framework-1e6.txt"
taskset -c 0 $B/bench_controller --iters 10000000 --reps 3 --only engine | tee "$RES/framework-1e7.txt"
sec "3a. ref, idle-skip off, N = 10^4: 4 runs in one JVM"
(cd "$REF" && taskset -c 0 $J -Dmeshsim.skip=false -cp "$CP" SpeedRun 0 "$W/l4/loop.code.bin" 4) | tee "$RES/ref-skip-off.txt"
sec "3b. the framework, N = 10^4, 3 runs"
taskset -c 0 $B/bench_controller --iters 10000 --reps 3 --only engine | tee "$RES/framework-1e4.txt"
grep -q 'DID NOT' "$RES"/*.txt && verdict "every run halts by SIM_EXIT" FAIL || verdict "every run halts by SIM_EXIT" PASS
grep -q 'count 1000000$' "$RES/ref-skip-on.txt" && grep -q 'count 10000$' "$RES/ref-skip-off.txt" && verdict "ref's runs end with the loop's count" PASS || verdict "ref's runs end with the loop's count" FAIL
sec "4. JFR of ref: idle-skip on (N = 10^6, 2 runs), off (N = 10^4, 2 runs); folded"
(cd "$REF" && taskset -c 0 $J -XX:StartFlightRecording=settings=profile,dumponexit=true,filename=$W/on.jfr -cp "$CP" SpeedRun 0 "$W/l6/loop.code.bin" 2) > "$W/jon.log" 2>&1; tail -2 "$W/jon.log"
(cd "$REF" && taskset -c 0 $J -XX:StartFlightRecording=settings=profile,dumponexit=true,filename=$W/off.jfr -Dmeshsim.skip=false -cp "$CP" SpeedRun 0 "$W/l4/loop.code.bin" 2) > "$W/joff.log" 2>&1; tail -2 "$W/joff.log"
for n in on off; do
  java -cp "$W/jt" JfrFold "$W/$n.jfr" 40 > "$RES/jfr-skip-$n.txt" 2>&1
  echo "-- idle-skip $n"; head -80 "$RES/jfr-skip-$n.txt"
done
sec "done in $(($(date +%s) - START)) s"
} 2>&1 | tee "$RES/run.log"
grep '^VERDICT' "$RES/run.log" > "$RES/VERDICTS.txt"
rm -rf "$W"
grep -q ': FAIL$' "$RES/VERDICTS.txt" && exit 1
exit 0
